package com.petlis.service.impl;
import com.fasterxml.jackson.databind.ObjectMapper;import com.petlis.common.exception.BusinessException;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.Import;import org.springframework.transaction.annotation.Transactional;
import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Import(LegacyBankJdbcTestConfiguration.class) @Transactional("legacyBankTestTransactions") @EnabledIfEnvironmentVariable(named="PETLIS_LOCAL_DB_TEST",matches="true")
class LegacyCustomerViewLocalDatabaseTest {
 @Autowired FeatureStore store;@Autowired ObjectMapper json;LegacyBankPaymentQuoteLocalDatabaseTest f;LegacyCustomerViewService service;
 @BeforeEach void setup(){f=new LegacyBankPaymentQuoteLocalDatabaseTest();f.store=store;f.json=json;f.setup();var animal=store.jdbc().queryForObject("SELECT MIN(InfoAnimalId) FROM lin_lb_infoanimal",Long.class);assertNotNull(animal);store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET InfoAnimalId=?,AnimalName=?,MasterName=? WHERE ListDiagnosisProjectId=?",animal,f.prefix,f.prefix,f.order);store.jdbc().update("INSERT INTO lin_operational_config(config_key,config_value,description,updated_by) VALUES('legacy-customer-views','{\"enabled\":true}','transaction-only customer fixture',?) ON DUPLICATE KEY UPDATE config_value=VALUES(config_value),status='ACTIVE'",f.actor);service=new LegacyCustomerViewService(store,f.access,new LegacyReportLinks("https://petlis.invalid/","public-customer-view-test"));}
 long detail(){return store.jdbc().queryForObject("SELECT MIN(DiagnosisDetailId) FROM lin_lb_diagnosisdetail WHERE ListDiagnosisProjectId=?",Long.class,f.order);}
 LegacyCustomerViewService.Command cid(){return new LegacyCustomerViewService.Command("CID",detail(),null);}
 @Test void cashGateRetainsFreightAndStrict1970ReceiptCondition(){store.jdbc().update("UPDATE lin_lb_infohospital SET PayType=0 WHERE InfoHospitalId=?",f.hospital);f.detail(246,"12.50",0,0);f.detail(f.test,"9.99",0,0);var r=service.previewAt(cid(),LocalDate.of(2024,3,20));assertEquals("12.50",r.get("amount"));assertEquals(true,r.get("needPay"));store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET ReceiveSampleDt='1970-01-01 00:00:00' WHERE ListDiagnosisProjectId=?",f.order);assertEquals("12.50",service.previewAt(cid(),LocalDate.of(2024,3,20)).get("amount"));store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET ReceiveSampleDt='1970-01-01 00:00:01' WHERE ListDiagnosisProjectId=?",f.order);assertEquals("22.49",service.previewAt(cid(),LocalDate.of(2024,3,20)).get("amount"));}
 @Test void monthlyDebtUsesInclusiveBoundaryAndZeroPriceStillBlocksReport(){f.detail(f.test,"12.50",0,0);long id=detail();store.jdbc().update("UPDATE lin_lb_diagnosisdetail SET PDFHttpUrl='https://petlis.invalid/owned.pdf' WHERE DiagnosisDetailId=?",id);store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET ReceiveSampleDt='2024-03-10 12:00:00' WHERE ListDiagnosisProjectId=?",f.order);long requested=f.order;long old=LegacyDetailFixtures.order(store,f.prefix+"_old",f.actor);store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET InfoHospitalId=?,ReceiveSampleDt='2024-02-01 00:00:00' WHERE ListDiagnosisProjectId=?",f.hospital,old);f.order=old;f.detail(f.test,"0.00",0,0);f.order=requested;var command=new LegacyCustomerViewService.Command("CID",id,null);var r=service.previewAt(command,LocalDate.of(2024,3,20));assertEquals(true,r.get("needPay"));assertEquals("HOSPITAL_BILL",r.get("nextAction"));assertEquals(false,r.get("reportAllowed"));store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET ReceiveSampleDt='2024-02-01 00:00:01' WHERE ListDiagnosisProjectId=?",old);r=service.previewAt(command,LocalDate.of(2024,3,20));assertEquals(false,r.get("needPay"));assertEquals(true,r.get("reportAllowed"));assertEquals("REPORT",r.get("nextAction"));store.jdbc().update("UPDATE lin_lb_diagnosisdetail SET PDFHttpUrl='0' WHERE DiagnosisDetailId=?",id);assertEquals(false,service.previewAt(command,LocalDate.of(2024,3,20)).get("reportAllowed"));}
 @Test void hospitalSummaryExcludesExemptAndKeepsIgnoredInPaidTotal(){store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET ReceiveSampleDt='2024-02-15 12:00:00' WHERE ListDiagnosisProjectId=?",f.order);f.detail(f.test,"1.00",0,0);f.detail(f.test,"2.00",1,0);f.detail(f.test,"3.00",4,0);f.detail(f.test,"4.00",0,1);var r=service.previewAt(new LegacyCustomerViewService.Command("HOSPITAL",f.hospital,null),LocalDate.of(2024,3,20));@SuppressWarnings("unchecked")var months=(List<Map<String,Object>>)r.get("months");assertEquals(1,months.size());assertEquals("6.00",months.get(0).get("TestPrice"));assertEquals("5.00",months.get(0).get("totalHasPayFee"));assertEquals("1.00",months.get(0).get("totalNoPayFee"));}
 @Test void legacyTokenAndExplicitGateAreRequiredAndPreviewDoesNotChangeOrder(){f.detail(f.test,"1.00",0,0);var before=store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.order);String token=LegacyLinkCodec.encrypt(String.valueOf(detail()),"public-customer-view-test");assertEquals(detail(),((Number)service.previewAt(new LegacyCustomerViewService.Command("CID",null,token),LocalDate.of(2024,3,20)).get("detailId")).longValue());assertEquals(before,store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.order));assertEquals(400,assertThrows(BusinessException.class,()->service.previewAt(new LegacyCustomerViewService.Command("CID",null,"bad"),LocalDate.of(2024,3,20))).getCode());store.jdbc().update("UPDATE lin_operational_config SET config_value='{\"enabled\":false}' WHERE config_key='legacy-customer-views'");assertEquals(409,assertThrows(BusinessException.class,()->service.previewAt(cid(),LocalDate.of(2024,3,20))).getCode());}
}
